CREATE TABLE IF NOT EXISTS opportunities (id TEXT PRIMARY KEY, owner_id TEXT REFERENCES "user"(id) ON DELETE SET NULL, published_version INTEGER, status TEXT NOT NULL DEFAULT 'unpublished' CHECK(status IN ('unpublished','open','paused','closed')), revision INTEGER NOT NULL DEFAULT 0, verified_at TIMESTAMPTZ, review_due_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS opportunity_submissions (id TEXT PRIMARY KEY, opportunity_id TEXT NOT NULL REFERENCES opportunities(id), author_id TEXT REFERENCES "user"(id) ON DELETE SET NULL, base_version INTEGER, previous_id TEXT REFERENCES opportunity_submissions(id), revision INTEGER NOT NULL DEFAULT 0, original_text TEXT NOT NULL DEFAULT '', data JSONB NOT NULL DEFAULT '{}', source JSONB NOT NULL DEFAULT '{}', status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','pending','returned','withdrawn','rejected','published')), feedback JSONB NOT NULL DEFAULT '{}', internal_note TEXT NOT NULL DEFAULT '', submitted_at TIMESTAMPTZ, reviewed_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE UNIQUE INDEX IF NOT EXISTS opportunity_one_editable ON opportunity_submissions(opportunity_id) WHERE status IN ('draft','pending');
CREATE TABLE IF NOT EXISTS opportunity_releases (opportunity_id TEXT NOT NULL REFERENCES opportunities(id), version INTEGER NOT NULL CHECK(version>0), submission_id TEXT NOT NULL UNIQUE REFERENCES opportunity_submissions(id), data JSONB NOT NULL, published_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), PRIMARY KEY(opportunity_id,version));
CREATE UNIQUE INDEX IF NOT EXISTS opportunity_release_pointer ON opportunity_releases(opportunity_id,version);
ALTER TABLE opportunities DROP CONSTRAINT IF EXISTS opportunity_current_release;
ALTER TABLE opportunities ADD CONSTRAINT opportunity_current_release FOREIGN KEY(id,published_version) REFERENCES opportunity_releases(opportunity_id,version);
CREATE TABLE IF NOT EXISTS opportunity_evidence (id TEXT PRIMARY KEY, submission_id TEXT NOT NULL REFERENCES opportunity_submissions(id), media_type TEXT NOT NULL, bytes INTEGER NOT NULL, digest TEXT NOT NULL, image BYTEA NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS opportunity_author_queue ON opportunity_submissions(author_id,created_at DESC);
CREATE INDEX IF NOT EXISTS opportunity_review_queue ON opportunity_submissions(status,submitted_at);
CREATE TABLE IF NOT EXISTS opportunity_reports (id TEXT PRIMARY KEY, opportunity_id TEXT NOT NULL, version INTEGER NOT NULL, author_id TEXT REFERENCES "user"(id) ON DELETE SET NULL, category TEXT NOT NULL, description TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','resolved','dismissed')), resolution TEXT NOT NULL DEFAULT '', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), resolved_at TIMESTAMPTZ, FOREIGN KEY(opportunity_id,version) REFERENCES opportunity_releases(opportunity_id,version));
CREATE TABLE IF NOT EXISTS opportunity_receipts (actor_id TEXT NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, request_id TEXT NOT NULL, fingerprint TEXT NOT NULL, result JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), PRIMARY KEY(actor_id,request_id));
